func publishedMigrationChecksum(version int, canonical string) string {
	if version > 0 && version <= len(publishedMigrationIdentities) {
		identity := publishedMigrationIdentities[version-1]
		if canonical == identity.canonical {
			return identity.published
		}
	}
	return canonical
}

func publishedMigrationSpecificationMatches(version int, canonical string) bool {
	return version > len(publishedMigrationIdentities) ||
		(version > 0 && canonical == publishedMigrationIdentities[version-1].canonical)
}

func publishedTranscriptCohortChecksum(canonical string) string {
	switch canonical {
	case "90054f7ad6d89d0e6101b454d87f41a4dbcf4372d124fd9674231e1c6e21dfa2":
		return transcriptV23CohortSHA256
	case "b0454f0552bb42aedbe3fb8b41fac5d51a047ce71de8abe2c3563f703844c549":
		return transcriptV24CohortSHA256
	case "9b997b2e515bb61035414328e4c312a54593c6aac1492587760ddb194e984865":
		return transcriptV25CohortSHA256
	default:
		return canonical
	}
}
